/*
  PingGraph — STEP 2 : SENDER (Waveshare ESP32-S3-ETH)
  W5500 Ethernet (DHCP) + real ICMP ping to 8.8.8.8 via ESP-IDF esp_ping.
  Result goes out over ESP-NOW once/sec. No libraries to install.
  Board: ESP32S3 Dev Module  (verify log says ...:esp32s3!) · USB CDC On Boot: Enabled
*/
#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>
#include <SPI.h>
#include <ETH.h>
#include "ping/ping_sock.h"
#include "lwip/ip_addr.h"

#define RGB_PIN 21                 // onboard WS2812 (now shows network state)

// W5500 pins (Waveshare ESP32-S3-ETH)
#define ETH_TYPE ETH_PHY_W5500
#define ETH_ADDR 1
#define ETH_CS   14
#define ETH_IRQ  10
#define ETH_RST   9
#define ETH_SCK  13
#define ETH_MISO 12
#define ETH_MOSI 11

#define ESPNOW_CHANNEL 1
uint8_t PEER_MAC[6] = { 0x70, 0x4B, 0xCA, 0x7B, 0x95, 0xEC };

typedef struct __attribute__((packed)) {
  uint32_t seq;
  uint16_t rtt_ms;
  uint8_t  status;    // 0=OK, 1=PING TIMEOUT, 2=NO IP, 3=LINK DOWN
} probe_t;
uint32_t seq = 0;

// ---- esp_ping, wrapped as a blocking "ping once" --------------------------
static SemaphoreHandle_t ping_done;
static volatile uint32_t ping_rtt = 0;
static volatile bool     ping_ok  = false;

static void ping_success(esp_ping_handle_t h, void *a) {
  uint32_t t; esp_ping_get_profile(h, ESP_PING_PROF_TIMEGAP, &t, sizeof(t));
  ping_rtt = t; ping_ok = true;
}
static void ping_timeout(esp_ping_handle_t h, void *a) { ping_ok = false; }
static void ping_end(esp_ping_handle_t h, void *a) {
  esp_ping_delete_session(h); xSemaphoreGive(ping_done);
}

bool pingOnce(uint16_t &rttOut) {
  ip_addr_t target; memset(&target, 0, sizeof(target));
  ipaddr_aton("8.8.8.8", &target);
  esp_ping_config_t cfg = ESP_PING_DEFAULT_CONFIG();
  cfg.target_addr = target; cfg.count = 1; cfg.timeout_ms = 1000;
  esp_ping_callbacks_t cbs = {};
  cbs.on_ping_success = ping_success;
  cbs.on_ping_timeout = ping_timeout;
  cbs.on_ping_end     = ping_end;
  ping_ok = false; ping_rtt = 0;
  esp_ping_handle_t h;
  if (esp_ping_new_session(&cfg, &cbs, &h) != ESP_OK) return false;
  esp_ping_start(h);
  xSemaphoreTake(ping_done, pdMS_TO_TICKS(1500));
  rttOut = ping_rtt > 65535 ? 65535 : (uint16_t)ping_rtt;
  return ping_ok;
}

void setLed(uint8_t s) {
  switch (s) {
    case 0:  neopixelWrite(RGB_PIN, 0, 40, 0);  break; // green  OK
    case 1:  neopixelWrite(RGB_PIN, 50, 15, 0); break; // orange ping timeout
    case 2:  neopixelWrite(RGB_PIN, 40, 30, 0); break; // yellow no IP
    default: neopixelWrite(RGB_PIN, 40, 0, 0);  break; // red    link down
  }
}

#if ESP_ARDUINO_VERSION >= ESP_ARDUINO_VERSION_VAL(4,0,0)
void onDataSent(const wifi_tx_info_t *info, esp_now_send_status_t st) {
#else
void onDataSent(const uint8_t *mac, esp_now_send_status_t st) {
#endif
  if (st != ESP_NOW_SEND_SUCCESS) Serial.println("  (espnow: no ACK from CYD)");
}

void setup() {
  Serial.begin(115200); delay(300);
  neopixelWrite(RGB_PIN, 30, 30, 30);       // white = booting
  ping_done = xSemaphoreCreateBinary();

  // ESP-NOW (radio up, never joins an AP)
  WiFi.mode(WIFI_STA); WiFi.disconnect();
  esp_wifi_set_channel(ESPNOW_CHANNEL, WIFI_SECOND_CHAN_NONE);
  Serial.print("Sender MAC: "); Serial.println(WiFi.macAddress());
  if (esp_now_init() != ESP_OK) { Serial.println("espnow init fail"); return; }
  esp_now_register_send_cb(onDataSent);
  esp_now_peer_info_t peer = {};
  memcpy(peer.peer_addr, PEER_MAC, 6);
  peer.channel = ESPNOW_CHANNEL; peer.encrypt = false;
  esp_now_add_peer(&peer);

  // Ethernet (W5500 over SPI)
  SPI.begin(ETH_SCK, ETH_MISO, ETH_MOSI);
  ETH.begin(ETH_TYPE, ETH_ADDR, ETH_CS, ETH_IRQ, ETH_RST, SPI);
  Serial.println("Ethernet starting (waiting for link + DHCP)...");
}

bool ipPrinted = false;

void loop() {
  unsigned long t0 = millis();
  probe_t pkt; pkt.seq = seq++; pkt.rtt_ms = 0;

  if (!ETH.linkUp()) {
    pkt.status = 3; ipPrinted = false;                       // LINK DOWN
  } else if (ETH.localIP() == IPAddress((uint32_t)0)) {
    pkt.status = 2;                                           // NO IP
  } else {
    if (!ipPrinted) { Serial.print("Got IP: "); Serial.println(ETH.localIP()); ipPrinted = true; }
    uint16_t rtt;
    if (pingOnce(rtt)) { pkt.status = 0; pkt.rtt_ms = rtt; }  // OK
    else               { pkt.status = 1; }                    // PING TIMEOUT
  }

  setLed(pkt.status);
  esp_now_send(PEER_MAC, (uint8_t *)&pkt, sizeof(pkt));
  Serial.printf("seq=%lu status=%u rtt=%u\n",
                (unsigned long)pkt.seq, pkt.status, pkt.rtt_ms);

  unsigned long el = millis() - t0;          // hold ~1s cadence
  if (el < 1000) delay(1000 - el);
}
